--[[
    Array of {
        parent: index into this array |nil
        icon: string
        name: string
        contents: table, can be passed into `spawnmenu.AddPropCategory`
    }
]]
local DATA = util.JSONToTable(DATA_TEXT)

hook.Add("PopulatePropMenu", "stpM64.Spawnlist", function()
    local id_offset = table.maxn(spawnmenu.GetCustomPropTable())

    for id, params in ipairs(DATA) do
        local id = id + id_offset
        local parent_id

        if params.parent ~= nil then
            parent_id = params.parent + id_offset
        end

        spawnmenu.AddPropCategory(
            "stpm64_"..tostring(id),
            params.name,
            params.contents,
            params.icon,
            id,
            parent_id
        )
    end
end)


concommand.Add("stpm64_convert_spawnlist", function(_,_,args)
    local root_id = args[1]
    if root_id == nil then
        print("Usage: stpm64_convert_spawnlist <spawnlist id, positive integer>")
        return
    end

    root_id = tonumber(root_id)

    if root_id == nil or root_id < 1 then
        print("Usage: stpm64_convert_spawnlist <spawnlist id, positive integer>")
        return
    end

    local spawnlist_data = {}

    for _, spawnlist in pairs(spawnmenu.GetPropTable()) do
        spawnlist_data[spawnlist.id] = spawnlist
    end

    if spawnlist_data[root_id] == nil then
        print("Error: spawnlist with given ID not found!")
        return
    end

    local function MarkUsed(id)
        if spawnlist_data[id]._used then return end

        spawnlist_data[id]._used = true

        for nextid, spawnlist in pairs(spawnlist_data) do
            if spawnlist.parentid == id then
                MarkUsed(nextid) 
            end
        end
    end

    MarkUsed(root_id)

    local out_data = {}
    local spawnlist_id_to_out_idx = {}

    for _, spawnlist in SortedPairs(spawnlist_data) do
        if not spawnlist._used then continue end

        spawnlist_id_to_out_idx[spawnlist.id] = table.insert(out_data, {
            icon = spawnlist.icon,
            name = spawnlist.name,
            _oldid = spawnlist.id,

            contents = spawnlist.contents
        })
    end

    for id, spawnlist in ipairs(out_data) do
        spawnlist.parent = 
            spawnlist_id_to_out_idx[spawnlist_data[spawnlist._oldid].parentid]

        spawnlist._oldid = nil
    end

    local out_json = util.TableToJSON(out_data, false)

    local out_path = "generated_spawnlist_data.txt"

    print("Writing...")
    file.Write(out_path, out_json)
    print("Wrote result to data/"..out_path)
end)
